SELECT p.pid,t.tid,t.name,t.is_main_thread FROM thread t JOIN process p USING(upid) WHERE p.pid IN (6294,6859,7540,8041,8676,9240,9745,10234,10762,11178) AND (t.tid IN (6316,6316,6883,6883,7561,7561,8063,8063,8696,8696,9261,9261,9769,9769,10259,10259,10787,10787,11202,11202) OR t.tid=p.pid) ORDER BY p.pid,t.tid;
